public class EventManager {
    private Dictionary<string, List<Action<object>>> events = new Dictionary<string, List<Action<object>>();

    public void Subscribe(string event, Action<object> callback) {
        if (!events.ContainsKey(event) {
            events[event] = new List<Action<object>>();
        }
        events[event].Add(callback);
    }

    public void Trigger(string event, object data) {
        if (events.ContainsKey(event)) {
            foreach (var callback in events[event]) {
                callback(data);
