public class PerformanceProfiler {
    private Dictionary<string, List<float>> frames;

    public PerformanceProfiler() {
        frames = new Dictionary<string>();
    }

    public void StartProfiling(string name) {
        if (!frames.ContainsKey(name) {
            frames[name] = new List<float>();
        }
    }

    public void EndProfiling(string name) {
        float deltaTime = GetDeltaTime(); // Assuming you have a method to get deltaTime

        if (frames.ContainsKey(name)) {
    frames[name].Add(deltaTime);
    }
}

public void Update() {
    // Call this every frame
    EndProfiling("Render");
    // Or
    EndProfiling("Update");

    // Clear old frames if needed
    CleanUp();
}

public void CleanUp() {
    foreach (KeyValuePair<string, List<float>> entry in frames) {
        while (entry.Value.Count > 100) {
            entry.Value.RemoveAt(0);
        }
}
```

This will help you track performance for different sections of your code, making it easier to optimize and ensure smooth performance. Remember to clear old frames to keep it from eating up too much memory.

